<?php
require 'config.php'; require_login();
if(isset($_POST['simpan']) && is_admin()){
 $stmt=$pdo->prepare("INSERT INTO barang(nama_barang,kategori,satuan,stok,stok_minimum) VALUES(?,?,?,?,?)");
 $stmt->execute([trim($_POST['nama']),trim($_POST['kategori']),trim($_POST['satuan']),max(0,(int)$_POST['stok']),max(0,(int)$_POST['minimum'])]); redirect('barang.php');
}
if(isset($_POST['hapus']) && is_admin()){ $stmt=$pdo->prepare("DELETE FROM barang WHERE id_barang=?"); try{$stmt->execute([$_POST['id']]);}catch(Exception $e){} redirect('barang.php');}
$q=trim($_GET['q']??''); $stmt=$pdo->prepare("SELECT * FROM barang WHERE nama_barang LIKE ? OR kategori LIKE ? ORDER BY nama_barang"); $stmt->execute(["%$q%","%$q%"]); $items=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data Barang</title><link rel="stylesheet" href="style.css"></head><body><?php include 'nav.php'; ?><main class="main"><header class="page-head"><div><p class="eyebrow">INVENTORY</p><h1>Data Barang</h1><p class="muted">Daftar barang yang tersimpan di gudang.</p></div><?php if(is_admin()): ?><button class="btn primary" onclick="document.getElementById('modal').classList.add('show')">+ Tambah barang</button><?php endif ?></header><section class="panel"><form class="search" method="get"><input name="q" placeholder="Cari nama atau kategori barang..." value="<?= htmlspecialchars($q) ?>"><button class="btn">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Nama barang</th><th>Kategori</th><th>Satuan</th><th>Stok</th><th>Stok minimum</th><th>Status</th><?php if(is_admin()): ?><th></th><?php endif ?></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><b><?= htmlspecialchars($i['nama_barang']) ?></b></td><td><?= htmlspecialchars($i['kategori']) ?></td><td><?= htmlspecialchars($i['satuan']) ?></td><td><?= $i['stok'] ?></td><td><?= $i['stok_minimum'] ?></td><td><span class="badge <?= $i['stok']<=$i['stok_minimum']?'orange':'green' ?>"><?= $i['stok']<=$i['stok_minimum']?'Menipis':'Aman' ?></span></td><?php if(is_admin()): ?><td><form method="post" onsubmit="return confirm('Hapus barang ini?')"><input type="hidden" name="id" value="<?= $i['id_barang'] ?>"><button name="hapus" class="text-btn">Hapus</button></form></td><?php endif ?></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="7" class="empty">Barang tidak ditemukan.</td></tr><?php endif ?></tbody></table></div></section></main>
<?php if(is_admin()): ?><div class="modal" id="modal"><div class="modal-card"><div class="panel-head"><h2>Tambah barang</h2><button class="text-btn" onclick="document.getElementById('modal').classList.remove('show')">✕</button></div><form method="post"><label>Nama barang</label><input name="nama" required><label>Kategori</label><input name="kategori" required><label>Satuan</label><input name="satuan" placeholder="pcs, box, kg" required><div class="form-row"><div><label>Stok awal</label><input type="number" min="0" name="stok" value="0" required></div><div><label>Stok minimum</label><input type="number" min="0" name="minimum" value="5" required></div></div><button class="btn primary full" name="simpan">Simpan barang</button></form></div></div><?php endif ?></body></html>
